                {
                    b.Property<string>("Name")
                        .HasMaxLength(64)
                        .IsUnicode(false)
                        .HasColumnType("varchar(64)");

                    b.Property<DateTime?>("ExpiresAt")
                        .HasColumnType("datetime2(3)");

                    b.Property<string>("Owner")
                        .HasMaxLength(64)
                        .IsUnicode(false)
                        .HasColumnType("varchar(64)");

                    b.Property<Guid?>("Token")
                        .HasColumnType("uniqueidentifier");

                    b.HasKey("Name");

                    b.ToTable("SweeperLease", "inventory", t =>
                        {
                            t.HasCheckConstraint("CK_SweeperLease_Owner", "([Owner] IS NULL AND [Token] IS NULL AND [ExpiresAt] IS NULL) OR ([Owner] IS NOT NULL AND [Token] IS NOT NULL AND [ExpiresAt] IS NOT NULL)");
                        });

                    b.HasData(
                        new
                        {
                            Name = "hold-expiry"
                        });
                });

